ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id;
    int ret;

    if (out_len < sizeof(*cmd)) {
        return -EINVAL;
    }

    id = ucma_get_id(file);
    if (!id)
        return -ENODEV;

    if (cmd->addr_size > sizeof(cmd->addr))
        return -EINVAL;

    mcast = kmalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast) {
        ret = -ENOMEM;
        goto out;
    }

    mcast->id = id;
    memcpy(&mcast->addr, &cmd->addr, cmd->addr_size);
    mcast->flags = cmd->flags;

    ret = rdma_join_ip_multicast(id, &mcast->addr, cmd->flags);
    if (ret) {
        kfree(mcast);
        goto out;
    }

    id->mcast = mcast;

    cmd->addr_size = sizeof(cmd->addr);
    ret = 0;

out:
    ucma_put_id(id);
    return ret;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len) {
    int ret;
    struct rdma_mcast *mcast;
    struct rdma_user_mcast *umcast;
    struct rdma_cm_id *id;

    if (out_len < sizeof(*umcast))
        return -EINVAL;

    if (cmd->addr_len < sizeof(struct sockaddr))
        return -EINVAL;

    if (cmd->flags & RDMA_MCAST_JOIN_FLAG)
        return -EINVAL;

    id = file->id;
    if (!id)
        return -EINVAL;

    mcast = kzalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast)
        return -ENOMEM;

    mcast->id = id;
    mcast->addr_len = cmd->addr_len;
    memcpy(&mcast->addr, &cmd->addr, cmd->addr_len);
    mcast->join_state = RDMA_MCAST_JOIN;

    ret = rdma_mcast_join(id, &mcast->addr, mcast->addr_len);
    if (ret < 0) {
        kfree(mcast);
        return ret;
    }

    umcast = kmalloc(sizeof(*umcast), GFP_KERNEL);
    if (!umcast) {
        ret = -ENOMEM;
        goto err_out;
    }

    umcast->id = id->id;
    umcast->addr_len = mcast->addr_len;
    memcpy(&umcast->addr, &mcast->addr, mcast->addr_len);

    if (copy_to_user((void __user *)(uintptr_t)cmd->response, umcast, sizeof(*umcast))) {
        ret = -EFAULT;
        kfree(umcast);
        goto err_out;
    }

    kfree(umcast);
    return 0;

err_out:
    rdma_mcast_leave(id, &mcast->addr);
    kfree(mcast);
    return ret;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    struct rdma_mcast *mcast;
    struct sockaddr *addr;
    struct rdma_cm_id *id;
    int ret;

    if (out_len < sizeof(*cmd))
        return -EINVAL;

    if (cmd->addr_len < sizeof(*addr))
        return -EINVAL;

    if (cmd->flags & RDMA_MCAST_JOIN_FLAG)
        return -EINVAL;

    id = ucma_get_id(file);
    if (!id)
        return -EINVAL;

    addr = (struct sockaddr *)cmd + sizeof(*cmd);
    mcast = kmalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast) {
        ret = -ENOMEM;
        goto out;
    }

    ret = rdma_join_ip_multicast(id, addr, cmd->qpn, mcast);
    if (ret)
        goto out_free;

    cmd->response = RDMA_MCAST_RESP_SUCCESS;
    if (copy_to_user(file->umem, cmd, sizeof(*cmd))) {
        ret = -EFAULT;
        goto out_free;
    }

    return 0;

out_free:
    kfree(mcast);
out:
    rdma_put_id(id);
    return ret;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    int ret;
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id = file->context;

    if (out_len < sizeof(*cmd)) {
        return -EINVAL;
    }

    if (cmd->addr_len != sizeof(struct sockaddr_in) &&
        cmd->addr_len != sizeof(struct sockaddr_in6)) {
        return -EINVAL;
    }

    mcast = kmalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast)
        return -ENOMEM;

    mcast->addr_len = cmd->addr_len;
    memcpy(&mcast->addr, &cmd->addr, cmd->addr_len);
    mcast->id = id;

    ret = rdma_join_ip_multicast(id, &mcast->addr, cmd->flags);
    if (ret) {
        kfree(mcast);
        return ret;
    }

    cmd->cookie = (uintptr_t)mcast;
    return 0;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    struct rdma_ucm_join_mcast_resp resp = {};
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id;
    int ret;

    if (out_len < sizeof(resp))
        return -EINVAL;

    if (cmd->addr_len < sizeof(struct sockaddr_in))
        return -EINVAL;

    if (cmd->flags & RDMA_MCAST_JOIN_FLAG_LEAVE)
        return -EINVAL;

    id = ucma_get_ctx(file);
    if (!id)
        return -EBADF;

    mcast = kzalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast) {
        ret = -ENOMEM;
        goto err;
    }

    mcast->id = id;
    mcast->group_id = cmd->group_id;
    mcast->addr_len = cmd->addr_len;
    memcpy(&mcast->addr, &cmd->addr, cmd->addr_len);

    ret = rdma_mcast_join(id, &mcast->addr, cmd->flags);
    if (ret)
        goto err_free;

    resp.group_id = mcast->group_id;
    if (copy_to_user(cmd->resp, &resp, sizeof(resp)))
        ret = -EFAULT;

    return 0;

err_free:
    kfree(mcast);
err:
    return ret;
}
